import { assets } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    assettagged: Boolean,
    adminassetItems: Object
  },
  data() {
    return {
      loading: false
    };
  },
  watch: {
    assettagged: {
      async handler() {
        await this.fetch_assetretire();
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.form.resetValidation();
      this.$refs.form.reset();
    },
    async delete_mutation() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(assets, {
          input: {
            asset_id: this.adminassetItems.asset_id,
            action_type: "UPDATE_ASSET_STATUS",
            asset_status: this.adminassetItems.asset_status != "ACTIVE" ? "ACTIVE" : "DEACTIVE"
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.assets);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
